--
-- Table structure for table `pedido`
--

DROP TABLE IF EXISTS `pedido`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pedido` (
  `id_pedido` int NOT NULL AUTO_INCREMENT,
  `status` varchar(20) DEFAULT NULL,
  `recebido` datetime DEFAULT NULL,
  `inicio_preparo` datetime DEFAULT NULL,
  `saida` datetime DEFAULT NULL,
  `entrega` datetime DEFAULT NULL,
  `cancelamento` datetime DEFAULT NULL,
  `restaurante_id_restaurante` int NOT NULL,
  `entregador_id_entregador` int NOT NULL,
  `id_cliente` int NOT NULL,
  `endereco_cep` varchar(9) NOT NULL,
  `endereco_num_end` int NOT NULL,
  PRIMARY KEY (`id_pedido`,`restaurante_id_restaurante`,`entregador_id_entregador`,`id_cliente`,`endereco_cep`,`endereco_num_end`),
  KEY `fk_pedido_restaurante1_idx` (`restaurante_id_restaurante`),
  KEY `fk_pedido_entregador1_idx` (`entregador_id_entregador`),
  KEY `fk_pedido_cliente_has_endereco1_idx` (`id_cliente`,`endereco_cep`,`endereco_num_end`),
  CONSTRAINT `fk_pedido_cliente_has_endereco1` FOREIGN KEY (`id_cliente`, `endereco_cep`, `endereco_num_end`) REFERENCES `cliente_has_endereco` (`cliente_id_cliente`, `endereco_cep`, `endereco_num_end`),
  CONSTRAINT `fk_pedido_entregador1` FOREIGN KEY (`entregador_id_entregador`) REFERENCES `entregador` (`id_entregador`),
  CONSTRAINT `fk_pedido_restaurante1` FOREIGN KEY (`restaurante_id_restaurante`) REFERENCES `restaurante` (`id_restaurante`)
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pedido`
--

LOCK TABLES `pedido` WRITE;
/*!40000 ALTER TABLE `pedido` DISABLE KEYS */;
